import { chromium } from 'playwright-core';

const APP_URL = process.env.APP_URL || 'http://localhost:5539';
const RUN_DIR = '/tmp/live-qa/todo-353-s4-fix-84065';

const results = [];
function record(id, pass, detail) {
  results.push({ id, pass, detail });
  console.log(`${pass ? 'PASS' : 'FAIL'} ${id} — ${detail}`);
}

const browser = await chromium.launch();
const page = await browser.newPage();
page.on('console', (msg) => {
  if (msg.type() === 'error') console.log('[console.error]', msg.text());
});
page.on('pageerror', (err) => console.log('[pageerror]', err));

await page.goto(APP_URL, { waitUntil: 'domcontentloaded' });

const input = page.getByTestId('chat-composer-input');
await input.waitFor({ state: 'visible', timeout: 30000 });
await page.screenshot({ path: `${RUN_DIR}/01-loaded.png` });

// --- S4: Escape after an unmatched trigger token leaves focus in the composer ---
await input.click();
await input.fill('');
await input.type('/zzz', { delay: 20 });
await page.waitForTimeout(300);
const popoverVisible = await page.getByTestId('composer-trigger-popover').isVisible().catch(() => false);
record('S4-pre', !popoverVisible, `popover visible=${popoverVisible} after typing an unmatched token (expect closed)`);

await page.keyboard.press('Escape');
await page.waitForTimeout(150);
const activeTestIdAfterEscape = await page.evaluate(() => document.activeElement?.getAttribute('data-testid'));
record(
  'S4',
  activeTestIdAfterEscape === 'chat-composer-input',
  `active element data-testid after Escape = ${activeTestIdAfterEscape} (expect chat-composer-input)`,
);
await page.screenshot({ path: `${RUN_DIR}/02-after-escape.png` });

// --- Original bug: Enter after an unmatched token submits the message as plain text ---
await input.click();
await input.type('/zzz-unmatched-smoke', { delay: 15 });
await page.waitForTimeout(200);
await page.keyboard.press('Enter');
await page.waitForTimeout(500);
const textAfterEnter = await input.inputValue();
const sawUserTurn = await page
  .getByText('/zzz-unmatched-smoke', { exact: false })
  .first()
  .isVisible()
  .catch(() => false);
record(
  'ENTER-SUBMIT',
  textAfterEnter === '' && sawUserTurn,
  `composer text after Enter = "${textAfterEnter}" (expect empty), transcript shows sent text = ${sawUserTurn}`,
);
await page.screenshot({ path: `${RUN_DIR}/03-after-enter.png` });

